/**
 * Close the pre-model window and leave its timing row.
 *
 * FORK 2026-08-16 — `preparingSince` had NO close site for the normal, successful path. It was
 * cleared only on disconnect, on the next send, and on send failure; when the model was finally
 * named the pill simply stopped rendering because `viewedSessionBusy()` became true, and the
 * window it had been counting was never closed or recorded. That is precisely why the longest
 * stage of the turn was the one stage that left no tag.
 *
 * Idempotent: the first caller wins, so wiring it to several run-admission sites is safe.
 *
 * FORK 2026-10-05 — `runId` is the run that just named its model. A block opened only by the
 * client windows ("sending", "preparing context") names no run until a gateway stage does, so the
 * answer rail could not find the turn's model through it (chat-rail.ts reads `_phaseRunId`). The
 * block gets the run here when it has none; a stage that names one later is never overridden.
 * Only while THIS tab's pre-model window is open: send() resets the live block, so the block is
 * then this turn's own, never an older one a run started elsewhere would inherit.
 */
function closePreModelWindow(runId?: string): void {
  // Read before the window closes below; the stamp runs after, once "preparing context" has been
  // recorded, because recording it is what creates the block when no stage has.
  const ownWindowOpen = preparingSince !== null || pendingSince !== null;
  if (preparingSince !== null) {
    // FORK 2026-08-23 — attach the runner stages collected during this window. This is the
    // only moment they can be attached: the row is created here, and the stages are only
    // complete once a model has been named.
    // FORK 2026-08-24 — a stage OWNED by a plugin is rendered under that plugin's own row (see the
    // promotion branch in the turn-phase consumer). It must not ALSO appear here: the same
    // milliseconds in two breakdowns is how a reader ends up double-counting the biggest plugin
    // on the path, and the two panels would visibly disagree with each other.
    const unownedStages = preparingStages.filter((s) => !stageOwner(s));
    recordPhaseTiming({
      ...finishedPhase(
        "preparing context",
        Date.now() - preparingSince,
        "client",
        unownedStages.length > 0 ? unownedStages : undefined,
        "stage",
      ),
      // The REAL start, not one derived back from the duration: this window is the one the
      // block's span is anchored on, and deriving it would drift by an event loop turn.
      startedAt: preparingSince,
    });
    preparingSince = null;
    preparingStages = [];
  }
  // A model named without `chat.send` having resolved would leave this dangling into the next
  // turn's measurement.
  pendingSince = null;
  if (runId && ownWindowOpen) {
    const group = livePhaseGroup();
    if (group && !group._phaseRunId) {
      group._phaseRunId = runId;
      const id = group._clientRowId;
      if (typeof id === "string" && id) {
        updateClientRow(sessionKey, id, group);
      }
    }
  }
}

// FORK 2026-05-17: the ONE place `budgetScope` is mutated (bible panels.md
// §147 #18 — one canonical scope concept). Both scope switches — Models
// (#budget-scope-toggle) and Prefrontal (#prefrontal-scope-toggle) — are
// views of this single state. Before this the prefrontal switch had NO
// click handler (dead control) and the Models handler never re-rendered
// prefrontal, so the panel ignored the toggle and went stale. The setter
// syncs BOTH switches' chrome and re-renders BOTH panels so they can never
// disagree and neither toggle is dead.
const SCOPE_TOGGLE_IDS = [
  "budget-scope-toggle",
  "prefrontal-scope-toggle",
  "amygdala-scope-toggle",
];
function syncScopeToggleChrome(): void {
  for (const id of SCOPE_TOGGLE_IDS) {
    const toggle = document.getElementById(id);
    if (!toggle) {
      continue;
    }
    toggle
      .querySelector(".ct-switch-track")
      ?.classList.toggle("ct-switch-track--on", budgetScope === "all");
    toggle.querySelectorAll(".ct-switch-label").forEach((b) => {
      b.classList.toggle(
        "ct-switch-label--active",
        (b as HTMLElement).dataset.scope === budgetScope,
      );
    });
  }
}
function setBudgetScope(next: "session" | "all"): void {
  if (next !== "session" && next !== "all") {
    return;
  }
  budgetScope = next;
  syncScopeToggleChrome();
  updateBudgetPanel();
  updatePrefrontalTree();
  if (budgetScope === "all") void fetchAmygdalaAll();
  else renderAmygdalaPanel();
}

let tabs: Tab[] = [];
// FORK (2026-04-21): initialize from localStorage so a hard refresh preserves
// focus on whichever tab was active pre-reload. Previously defaulted to "" and
// the connect handler fell through to "tab-main", losing sub-session focus.
// FORK 2026-08-02 (the architect): fold every pre-unification localStorage key into the unified
// ui-state store BEFORE its first read — this module-scope initializer (and the fractal
// toggle load further down) runs long before the boot block that also migrates
// (idempotent, so the second call there is a no-op). The try/catch stays: in
// blocked-storage contexts even ACCESSING window.localStorage throws (SecurityError),
// which ui-state's internal error-swallowing cannot catch for us at module init.
let activeTabId = (() => {
  try {
    migrateLegacyUiState();
    return getChoice("tab:active", "");
  } catch {
    return "";
  }
})();
// FORK 2026-08-16 (the architect: "when I close the browser and restart it, the tinker ui tabs that I had
// opened are not anymore"). The literal moved to panels/ui-state.ts, which now mirrors this key to
// the durable file alongside the rest of the UI chrome. Imported rather than re-declared: two
// spellings of one storage key is a bug whose only symptom is silently losing the tab list.
const TAB_STORAGE_KEY = TABS_KEY;
const TAB_TITLE_INTERVAL = 5;
// FORK 2026-06-04 — jarvis-upgrade task-mpzcjw6n-n45zs (Tab name summary): the sentinel icon
// prefixed to AUTO-summarized tab names so they're visually distinct from fortune-cookie names
// (zen/nature emoji), "🏠 Main" and "❤️ Heartbeat". Single-sourced here so it's trivially
// swappable. Manual renames keep whatever the user types; auto-naming (periodic + the right-click
// "Auto-name" action) both flow through generateTabTitle and get this prefix.
const AUTO_NAME_ICON = "🏷️";
let tabContextMenuEl: HTMLElement | null = null;

// FORK 2026-09-23 (the architect: "set conversation slave") — the chain list is read FRESH from the
// ui-state choice every time (it is tiny), so boot hydration from the durable file and a second
// window's edits are picked up without a separate sync path. Chains whose tab is not open are
// hidden, not deleted: a tab restored later gets its chain back. closeTab() is what unlinks.
let chainOverlay: ChainOverlay | null = null;

/** FORK 2026-09-25 — the little chain between a master row and its slave row in the sessions
 *  panel: eyelet on top (master), two links, collar at the bottom (slave), as on the tab bar.
 *  Drawn in currentColor; the pair sets it to the chain's metal. */
const SESSION_CHAIN_SVG =
  '<svg viewBox="0 0 10 26" width="10" height="26" focusable="false">' +
  '<circle cx="5" cy="3.2" r="2.3" fill="none" stroke="currentColor" stroke-width="1.4"/>' +
  '<rect x="2.7" y="6" width="4.6" height="7.4" rx="2.3" fill="none" stroke="currentColor" stroke-width="1.3"/>' +
  '<line x1="5" y1="11.6" x2="5" y2="17.2" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"/>' +
  '<rect x="2.7" y="15.4" width="4.6" height="6.4" rx="2.3" fill="none" stroke="currentColor" stroke-width="1.3"/>' +
  '<rect x="1.4" y="22.2" width="7.2" height="3.2" rx="1" fill="currentColor"/>' +
  "</svg>";

function loadTabChains(): TabChain[] {
  return parseChains(getChoice(LOOP_CHAINS_CHOICE, LOOP_CHAINS_DEFAULT));
}

function saveTabChains(chains: TabChain[]): void {
  setChoice(LOOP_CHAINS_CHOICE, serializeChains(chains), LOOP_CHAINS_DEFAULT);
  chainOverlay?.wake();
}

// FORK 2026-10-05 (the architect: "a dedicated tab to visualize [the gantt] … a slither tab (only a graph
// icon) between master and slave … attached to the master … connected in real time"). The board
// list is polled from tinker-prod-ui; renderTabs draws an icon-only tab right after each chain
// master that has one. Clicking it covers the chat area with the live chart (#gantt-view) while
// the master stays the active chat underneath, so nothing else about the tab model changes.
// `ganttViewFor` is the master tab id whose chart is on screen, or null.
let ganttBoards: GanttBoard[] = [];
let ganttBoardsLoaded = false;
let ganttViewFor: string | null = null;

function currentGanttBoards(): Map<string, GanttBoard> {
  return ganttBoardsByMaster(
    loadTabChains(),
    ganttBoards,
    (id) => tabs.find((t) => t.id === id)?.sessionKey,
    (a, b) => sessionKeyMatches(a, b),
  );
}

async function refreshGanttBoards(): Promise<void> {
  let next: GanttBoard[];
  try {
    const res = await fetch("/api/gantt/boards", { cache: "no-store" });
    // A server without the route (an older tinker-prod-ui) simply has no Gantt tabs.
    next = res.ok ? parseGanttBoards(await res.json()) : [];
  } catch (err) {
    console.error("[gantt] board list fetch failed", err);
    return;
  }
  const changed = JSON.stringify(next) !== JSON.stringify(ganttBoards);
  const first = !ganttBoardsLoaded;
  ganttBoards = next;
  ganttBoardsLoaded = true;
  if (first) {
    // A pushed build reloads the page: land back on the chart if that is where the architect was.
    const want = getChoice(GANTT_VIEW_CHOICE, "");
    if (want && currentGanttBoards().has(want)) {
      openGanttView(want);
      return;
    }
  }
  if (changed || first) renderTabs();
}

function openGanttView(masterTabId: string): void {
  const tab = tabs.find((t) => t.id === masterTabId);
  if (!tab?.sessionKey) return;
  // Switch first: applyTabSwitch closes any open chart, including this one.
  if (activeTabId !== masterTabId) switchToTab(masterTabId);
  ganttViewFor = masterTabId;
  setChoice(GANTT_VIEW_CHOICE, masterTabId, "");
  const pane = $("gantt-view");
  const frame = pane?.querySelector("iframe");
  if (pane && frame) {
    const src = ganttViewUrl(tab.sessionKey);
    if (frame.getAttribute("src") !== src) frame.setAttribute("src", src);
    pane.hidden = false;
  }
  renderTabs();
}

/** `render: false` from inside renderTabs, which is already drawing the result. */
function closeGanttView(opts: { render?: boolean } = {}): void {
  if (!ganttViewFor) return;
  ganttViewFor = null;
  setChoice(GANTT_VIEW_CHOICE, "", "");
  const pane = $("gantt-view");
  if (pane) {
    pane.hidden = true;
    // Unload it: the page polls every 15 s, and nobody is looking.
    pane.querySelector("iframe")?.setAttribute("src", "about:blank");
  }
  if (opts.render !== false) renderTabs();
}

// FORK 2026-09-25 (the architect: "when I close a tab linked by a master-slave chain, both tabs should
// close at once … open one from the sessions panel, both should open … side by side").
// A chained pair is one object: it closes, reopens, sorts and lists together. The chain now
// outlives a close (with both SESSION keys stored), so the pair can find itself again.

/** Chains with each end's session key refreshed from the open tabs. Not persisted. */
function liveTabChains(): TabChain[] {
  return withChainKeys(loadTabChains(), (id) => tabs.find((t) => t.id === id)?.sessionKey);
}

/** Persist the open ends' session keys: on link, and just before a paired close. */
function snapshotChainKeys(): void {
  saveTabChains(liveTabChains());
}

/** Keep chained pairs adjacent in the tab bar, master immediately before slave. The anchor's
 *  partner comes to it; without one the master jumps ahead of the slave. Main never moves.
 *  Returns whether the order changed (caller saves + renders). */
function applyChainAdjacency(anchorId?: string | null): boolean {
  const next = adjacentChainOrder(tabs, loadTabChains(), anchorId, (id) => id === "tab-main");
  if (next.every((t, i) => t.id === tabs[i]?.id)) return false;
  tabs = next;
  return true;
}

/** Bottom-centre of a tab's title, clamped into the visible tab bar. While the tab is being
 *  dragged the chain follows the ghost under the pointer, not the parked original. */
function tabChainAnchor(tabId: string): TabAnchor | null {
  const bar = $("tab-bar-scroll");
  if (!bar) return null;
  const dragging = tabDrag?.tabId === tabId && tabDrag.passedThreshold;
  const el = dragging
    ? tabDrag!.ghost
    : (bar.querySelector(`[data-tab-id="${CSS.escape(tabId)}"]`) as HTMLElement | null);
  if (!el) return null;
  const tab = el.getBoundingClientRect();
  if (!tab.width) return null;
  const title =
    (el.querySelector(".tab-title") as HTMLElement | null)?.getBoundingClientRect() ?? tab;
  const barRect = bar.getBoundingClientRect();
  const x = dragging
    ? title.left + title.width / 2
    : Math.min(Math.max(title.left + title.width / 2, barRect.left + 8), barRect.right - 8);
  return { x, y: title.bottom, tab };
}

function beginChainPick(masterId: string, x: number, y: number): void {
  if (!chainOverlay) return;
  const color = CHAIN_COLORS[nextChainColor(loadTabChains(), masterId) % CHAIN_COLORS.length];
  document.body.classList.add("tab-chain-picking");
  chainOverlay.beginPick(masterId, color, { x, y });
  renderTabs();
}

function endChainPick(): void {
  document.body.classList.remove("tab-chain-picking");
  chainOverlay?.endPick();
  renderTabs();
}

function saveActiveTabId(): void {
  // FORK 2026-08-02 (the architect): routed through the unified ui-state store ("" = default =
  // no entry). The empty-check keeps the old semantics — a blank id never clears the
  // last persisted focus.
  try {
    if (activeTabId) {
      setChoice("tab:active", activeTabId, "");
    }
  } catch {
    // Blocked-storage contexts — silent fail; refresh falls back to tab-main.
  }
}

function generateTabId(): string {
  return "tab-" + Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
}

// FORK 2026-06-25: dedup title generation by a RUNTIME-ONLY set (never persisted), so a
// stale/persisted titleGenerating flag can NEVER permanently block a rename. (The old guard
// keyed on the persisted tab.titleGenerating; a tab saved mid-generate restored "generating"
// forever and every future rename short-circuited — tabs "blinked for hours" + never renamed.)
// FORK 2026-07-21 — Map with start timestamps instead of a Set: an entry older than
// TITLE_INFLIGHT_STALE_MS is treated as abandoned (stranded await, lost ws frame,
// killed gateway turn) and no longer blocks the next rename. A plain Set once left
// tabs permanently un-renamable after a gateway restart stranded the in-flight RPC.
const titleInFlight = new Map<string, number>();
const TITLE_INFLIGHT_STALE_MS = 90_000;

function saveTabs() {
  try {
    // FORK (2026-04-21): persist tab-main too. Previously filtered out, which meant
    // `/clear`-rotated main-tab sessionKeys were lost on hard reset (gateway restart or
    // browser refresh), causing the connect handshake's `defs.mainSessionKey` default
    // to restore yesterday's agent:main:main session instead of the user's fresh
    // tinker:* continuation.
    // FORK 2026-06-25: NEVER persist titleGenerating — it is a transient in-flight/shimmer
    // flag; persisting it true strands a tab as "generating" forever (see titleInFlight above).
    // FORK 2026-09-21 — through writeTabList so closed-tab tombstones filter every write: a
    // second window still holding a tab closed here cannot write it back.
    writeTabList(tabs.map((t) => ({ ...t, titleGenerating: undefined })) as TabRecord[]);
    // FORK 2026-08-16 — write-through to the durable file. localStorage alone does not
    // survive a browser exit on this profile (clear-on-exit), which is why a restart used
    // to come back with a lone "🏠 Main". Debounced and coalescing, so the bursts of
    // saveTabs() that loadSessions() fires cost ONE POST. Inside the try on purpose: if
    // the setItem above threw, the cache and the file would disagree, and the mirror
    // reads the CACHE — it would faithfully persist the write that just failed.
    scheduleUiStateMirror();
  } catch {}
  persistSessionPanelOrder();
}

// FORK 2026-09-01 (the architect: drag-reorder tabs; sessions panel follows that order).
// Open tab keys occupy the front; keys that just left the tab bar stay immediately
// after that prefix. Explicit sessions.delete is the only prune. Called from
// saveTabs so close/reorder/create all write one list, and from the panel paint
// so a reconnect that restored tabs without saveTabs still syncs the rail.
function persistSessionPanelOrder(): void {
  const openKeys = sessionKeysOfTabs(tabs);
  const previous = getOrderedIds(SESSION_PANEL_ORDER_KEY);
  setOrderedIds(
    SESSION_PANEL_ORDER_KEY,
    mergeTabSessionOrder(openKeys, previous, sessionKeyMatches),
  );
}

function loadTabs() {
  try {
    const stored = JSON.parse(localStorage.getItem(TAB_STORAGE_KEY) || "[]") as Tab[];
    // FORK (2026-04-21): force-restore tab-main's title to "🏠 Main" on every load.
    // The old v1/v2 fortune-migration heuristic that used to stomp short titles was
    // removed — it was intentionally stomping good Ollama-generated titles like
    // "🔧 Fix auth bug" (short + emoji-prefixed by design), destroying tab-title
    // persistence for every tinker:* session on gateway restart / hard refresh.
    // v1/v2 migrations are months old at this point; any stale titles can be cleared
    // manually by closing and reopening the tab.
    let changed = false;
    for (const tab of stored) {
      // FORK 2026-06-25: titleGenerating is transient — clear any persisted "generating"
      // state on load so an old tab saved mid-generate isn't stuck blinking forever and the
      // dedup guard doesn't block its rename. (Defense-in-depth with the no-persist in saveTabs.)
      tab.titleGenerating = false;
      if (tab.id === "tab-main" && tab.title !== "🏠 Main") {
        tab.title = "🏠 Main";
        changed = true;
      }
    }
    if (changed) {
      localStorage.setItem(TAB_STORAGE_KEY, JSON.stringify(stored));
      // The other writer of this key, so it mirrors too — otherwise the "🏠 Main"
      // normalisation above would be re-applied on every single cold start instead of
      // being fixed once, and the file would keep serving the stale title back.
      scheduleUiStateMirror();
    }
    return stored;
  } catch {
    return [];
  }
}

// FORK 2026-06-10 — u3-tab-naming: persist a DELIBERATE (manual rename or auto-name) tab title to
// the server session store via sessions.patch, so the name is durable across ANY restart, browser,
// or device — not just this browser's localStorage. cookiePhraseUserSet=true tells the gateway's
// lazy-mint to never overwrite it with a random fortune cookie. Fire-and-forget; the next
// sessions.list surfaces it back as the session's cookiePhrase.
function persistTabNameToServer(tab: Tab) {
  if (!tab.sessionKey || !tab.isAttached || tab.id === "tab-main") return;
  const title = tab.title?.trim();
  if (!title) return;
  req("sessions.patch", {
    key: tab.sessionKey,
    cookiePhrase: title,
    cookiePhraseUserSet: true,
  }).catch(() => {});
}

